window.products.push({"id":823291,"name":"Safavieh Hudson Collection Nolita Leather Small Storage Bench, Off-White","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/A1Mey+L0-vL._AC_SL1500_.jpg","description":"The Safavieh Hudson Collection NoLIta Off-White Leather Small Storage Bench is the ultimate in style and comfort. Its chic and transitional design makes it a great accent for any living space. The classic NoLIta Small Storage Bench stands on sturdy beech wood legs, is upholstered in off white bicast leather and has a unique tufted design on all sides. The NoLIta Small Storage Bench features a unique hinged top that allows you to store your household items. You can use the NoLIta Small Storage Bench as an accent in any room or decor. No assembly required, this bench measures 30-inch wide by 18-inch deep by 18-inch tall.","images":["https://m.media-amazon.com/images/I/A1Mey+L0-vL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Safavieh","source_asin":"B004G1AFTU","category_path":"Home & Kitchen"},"sku":"BM-823291","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B004G1AFTU","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B004G1AFTU","price_pending":true,"merchant_ready":false});
