window.products.push({"id":823419,"name":"OXO Good Grips Coarse Grater uni directional Grater","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71dOwV5PEIL._AC_SL1500_.jpg","description":"The OXO Good Grips Coarse Grater is an essential cooking companion. Etched blades provide a sharp grating surface to make grating faster and easier. The Grater is ideal for coarse grating of soft and semi-soft cheeses, butter, apples, cabbages, potatoes, onions and more. A soft, comfortable, non-slip handle ensures a secure grip and cushions the hand during repetitive grating motions while a non-slip foot keeps the Grater steady on the countertop when in use. Dishwasher safe.","images":["https://m.media-amazon.com/images/I/71dOwV5PEIL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"OXO","source_asin":"B077KFNRZW","category_path":"Home & Kitchen"},"sku":"BM-823419","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B077KFNRZW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B077KFNRZW","price_pending":true,"merchant_ready":false});
